-- 店铺分账申请本地演示数据（100 条，utf8mb4 中文虚构，不含渠道密钥/账户）
SET NAMES utf8mb4;
USE qixi_crm_admin;

-- 对齐表结构

SET @qixi_ddl := (
  SELECT IF(
    (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='qixi_crm_a_merchant_profitsharing_application' AND COLUMN_NAME='applyment_id')=0,
    'ALTER TABLE `qixi_crm_a_merchant_profitsharing_application` ADD COLUMN `merchant_name` varchar(128) NOT NULL DEFAULT '''' AFTER `merchant_id`, ADD COLUMN `applyment_id` varchar(100) NOT NULL DEFAULT '''' AFTER `application_no`, ADD COLUMN `message` varchar(1000) NOT NULL DEFAULT '''' AFTER `description`',
    'SELECT 1'
  )
);
PREPARE qixi_stmt FROM @qixi_ddl; EXECUTE qixi_stmt; DEALLOCATE PREPARE qixi_stmt;
ALTER TABLE `qixi_crm_a_merchant_profitsharing_application`
  MODIFY COLUMN `status` enum('applied','approved','rejected','platform_rejected','auditing','shop_verify','completed','frozen','wechat_rejected') NOT NULL DEFAULT 'applied';

DELETE FROM qixi_crm_a_merchant_profitsharing_audit WHERE application_id BETWEEN 970001 AND 970100;
DELETE FROM qixi_crm_a_merchant_profitsharing_application WHERE id BETWEEN 970001 AND 970100;


UPDATE qixi_crm_a_merchant_profitsharing_application a
JOIN qixi_crm_a_merchant_view v ON v.merchant_id = a.merchant_id
SET a.merchant_name = v.merchant_name
WHERE a.id BETWEEN 970001 AND 970100;

SELECT COUNT(*) AS total FROM qixi_crm_a_merchant_profitsharing_application WHERE id BETWEEN 970001 AND 970100;
SELECT status, COUNT(*) cnt FROM qixi_crm_a_merchant_profitsharing_application WHERE id BETWEEN 970001 AND 970100 GROUP BY status ORDER BY cnt DESC;
SELECT id, applyment_id, application_no, merchant_id, merchant_name, status, message FROM qixi_crm_a_merchant_profitsharing_application WHERE id BETWEEN 970001 AND 970100 ORDER BY id DESC LIMIT 5;